13	    /// Creates an identifier after rejecting empty and path-like values.
14	    ///
15	    /// # Errors
16	    ///
17	    /// Returns [`ArtifactIdError`] when `value` is empty or could alter the
18	    /// canonical artifact path.
19	    pub fn new(value: impl Into<String>) -> Result<Self, ArtifactIdError> {
20	        let value = value.into();
21	        if value.is_empty() {
22	            return Err(ArtifactIdError::Empty);
23	        }
24	        if value.contains('/') || value.contains('\\') || value == "." || value == ".." {
