11	/// Portable canonical contracts supported by Wisp's initial registry.
12	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
13	pub enum Contract {
14	    /// A captured need.
15	    RequirementV1,
16	    /// Evidence informing a requirement.
17	    ResearchReportV1,
18	    /// A testable specification.
19	    SpecV1,
20	    /// An implementation plan.
21	    PlanV1,
22	    /// A workspace architecture map.
23	    ArchModelV1,
24	}
