52	const EMBEDDED_SPEC_V1_SCHEMA: &str = include_str!("../../../schemas/spec@1.json");
53	const EMBEDDED_REQUIREMENT_V1_SCHEMA: &str = include_str!("../../../schemas/requirement@1.json");
54	const EMBEDDED_RESEARCH_REPORT_V1_SCHEMA: &str =
55	    include_str!("../../../schemas/research-report@1.json");
56	const EMBEDDED_PLAN_V1_SCHEMA: &str = include_str!("../../../schemas/plan@1.json");
57	const EMBEDDED_ARCH_MODEL_V1_SCHEMA: &str = include_str!("../../../schemas/arch-model@1.json");
