59	/// Validate a parsed document against a selected pinned contract.
60	///
61	/// # Errors
62	///
63	/// Returns a typed error when the embedded schema is invalid or the document
64	/// does not conform to it.
65	pub fn validate_contract(contract: Contract, value: &Value) -> Result<(), SpecValidationError> {
66	    let source = match contract {
67	        Contract::RequirementV1 => EMBEDDED_REQUIREMENT_V1_SCHEMA,
68	        Contract::ResearchReportV1 => EMBEDDED_RESEARCH_REPORT_V1_SCHEMA,
69	        Contract::SpecV1 => EMBEDDED_SPEC_V1_SCHEMA,
70	        Contract::PlanV1 => EMBEDDED_PLAN_V1_SCHEMA,
71	        Contract::ArchModelV1 => EMBEDDED_ARCH_MODEL_V1_SCHEMA,
72	    };
73	    let schema: Value =
74	        serde_json::from_str(source).map_err(|error| SpecValidationError::SchemaDefinition {
75	            message: error.to_string(),
76	        })?;
77	    let validator = jsonschema::validator_for(&schema).map_err(|error| {
78	        SpecValidationError::SchemaDefinition {
79	            message: error.to_string(),
80	        }
81	    })?;
82	    validator
83	        .validate(value)
84	        .map_err(|error| SpecValidationError::SchemaViolation {
85	            message: error.to_string(),
86	        })
87	}
