89	/// A `spec@1` document that has passed both its JSON Schema and Wisp ID checks.
90	#[derive(Debug, Clone, PartialEq)]
91	pub struct ValidatedSpec {
92	    /// The validated artifact identifier.
93	    pub id: ArtifactId,
94	    /// The original parsed JSON document.
95	    pub value: Value,
96	}
97	
98	/// An error encountered while parsing or validating a `spec@1` document.
99	#[derive(Debug, Diagnostic, Error)]
100	pub enum SpecValidationError {
101	    /// The candidate bytes are not valid JSON.
102	    #[diagnostic(code(wisp::schema::invalid_json))]
103	    #[error("the spec document is not valid JSON: {source}")]
104	    InvalidJson {
105	        /// Candidate source used by human diagnostics.
106	        #[source_code]
107	        source_code: NamedSource<String>,
108	        /// The parser location in the candidate source.
109	        #[label("invalid JSON here")]
110	        span: SourceSpan,
111	        /// The underlying JSON parser error.
112	        #[source]
113	        source: serde_json::Error,
114	    },
115	    /// The embedded schema could not be compiled.
116	    #[diagnostic(code(wisp::schema::definition))]
117	    #[error("the embedded spec@1 schema is invalid: {message}")]
118	    SchemaDefinition {
119	        /// A stable diagnostic suitable for logs, not terminal presentation.
120	        message: String,
121	    },
122	    /// The candidate does not satisfy the `spec@1` JSON Schema.
123	    #[diagnostic(code(wisp::schema::violation))]
124	    #[error("the spec document violates spec@1: {message}")]
125	    SchemaViolation {
126	        /// The first validator diagnostic.
127	        message: String,
128	    },
129	    /// The schema-valid `id` is not safe for a Wisp artifact path.
130	    #[diagnostic(code(wisp::schema::unsafe_id))]
131	    #[error("the spec document has an unsafe ID: {source}")]
132	    UnsafeId {
133	        /// The artifact ID validation error.
134	        #[source]
135	        source: ArtifactIdError,
136	    },
137	}
138	
139	/// Parse and validate candidate JSON bytes as a `spec@1` document.
140	///
141	/// # Errors
142	///
143	/// Returns an error when the bytes are malformed, the document violates the
144	/// pinned schema, or its otherwise schema-valid ID is unsafe for Wisp paths.
145	pub fn validate_spec_json(input: &[u8]) -> Result<ValidatedSpec, SpecValidationError> {
146	    let value = serde_json::from_slice(input).map_err(|source| invalid_json(input, source))?;
147	    validate_spec_value(value)
148	}
149	
150	/// Validate an already parsed JSON value as a `spec@1` document.
151	///
152	/// # Errors
153	///
154	/// Returns an error when the document violates the pinned schema or its ID is
155	/// unsafe for Wisp artifact paths.
156	pub fn validate_spec_value(value: Value) -> Result<ValidatedSpec, SpecValidationError> {
157	    let schema: Value = serde_json::from_str(EMBEDDED_SPEC_V1_SCHEMA).map_err(|source| {
158	        SpecValidationError::SchemaDefinition {
159	            message: source.to_string(),
160	        }
161	    })?;
162	    let validator = jsonschema::validator_for(&schema).map_err(|error| {
163	        SpecValidationError::SchemaDefinition {
164	            message: error.to_string(),
165	        }
166	    })?;
167	    if let Err(error) = validator.validate(&value) {
168	        return Err(SpecValidationError::SchemaViolation {
169	            message: error.to_string(),
170	        });
171	    }
172	
173	    let id = value.get("id").and_then(Value::as_str).ok_or_else(|| {
174	        SpecValidationError::SchemaViolation {
175	            message: "spec@1 accepted a document without a string id".to_owned(),
176	        }
177	    })?;
178	    let id = ArtifactId::new(id).map_err(|source| SpecValidationError::UnsafeId { source })?;
179	
180	    Ok(ValidatedSpec { id, value })
181	}
182	
183	fn invalid_json(input: &[u8], source: serde_json::Error) -> SpecValidationError {
184	    let source_text = String::from_utf8_lossy(input).into_owned();
185	    let line = source.line().saturating_sub(1);
186	    let column = source.column().saturating_sub(1);
187	    let line_offset = source_text
188	        .lines()
189	        .take(line)
190	        .map(|line| line.len() + 1)
191	        .sum::<usize>();
192	    let offset = line_offset.saturating_add(column).min(source_text.len());
193	    SpecValidationError::InvalidJson {
194	        source_code: NamedSource::new("spec candidate", source_text),
195	        span: SourceSpan::from((offset, 1)),
196	        source,
197	    }
198	}
