143	    reason = "discovery keeps filesystem traversal and graph-link validation together"
144	)]
145	pub fn discover_graph(workspace: &Utf8Path) -> Result<ArtifactGraph, ArtifactError> {
146	    let contracts = [
147	        Contract::RequirementV1,
148	        Contract::ResearchReportV1,
149	        Contract::SpecV1,
150	        Contract::PlanV1,
151	        Contract::ArchModelV1,
152	    ];
153	    let mut graph = ArtifactGraph {
154	        artifacts: Vec::new(),
155	        links: Vec::new(),
156	        issues: Vec::new(),
157	    };
158	    for contract in contracts {
159	        let directory = workspace.join(contract.canonical_directory());
160	        let entries = match fs::read_dir(&directory) {
161	            Ok(entries) => entries,
162	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
163	            Err(source) => {
164	                return Err(ArtifactError::Filesystem {
165	                    path: directory,
166	                    source,
167	                });
168	            }
169	        };
170	        for entry in entries {
171	            let entry = entry.map_err(|source| ArtifactError::Filesystem {
172	                path: directory.clone(),
173	                source,
174	            })?;
175	            let path = Utf8PathBuf::from_path_buf(entry.path()).map_err(|_| {
176	                ArtifactError::Filesystem {
177	                    path: directory.clone(),
178	                    source: std::io::Error::other("non-UTF-8 artifact path"),
179	                }
180	            })?;
181	            if path.extension() != Some("json") {
182	                continue;
183	            }
184	            let relative = path.strip_prefix(workspace).unwrap_or(&path).to_owned();
185	            let bytes = fs::read(&path).map_err(|source| ArtifactError::Filesystem {
186	                path: path.clone(),
187	                source,
188	            })?;
189	            let document: serde_json::Value = match serde_json::from_slice(&bytes) {
190	                Ok(value) => value,
191	                Err(error) => {
192	                    graph.issues.push(GraphIssue {
193	                        path: relative,
194	                        field: "document",
195	                        message: error.to_string(),
196	                    });
197	                    continue;
198	                }
199	            };
200	            if let Err(error) = validate_contract(contract, &document) {
201	                graph.issues.push(GraphIssue {
202	                    path: relative,
203	                    field: "document",
204	                    message: error.to_string(),
205	                });
206	                continue;
207	            }
208	            let key = document
209	                .get("id")
210	                .and_then(serde_json::Value::as_str)
211	                .map_or_else(
212	                    || path.file_stem().unwrap_or_default().to_owned(),
213	                    ToOwned::to_owned,
214	                );
215	            graph.artifacts.push(DiscoveredArtifact {
216	                contract,
217	                path: relative,
218	                key,
219	                document,
220	            });
221	        }
222	    }
223	    for artifact in &graph.artifacts {
224	        for (field, target_contract) in link_fields(artifact.contract) {
225	            if let Some(target_key) = artifact
226	                .document
227	                .get(field)
228	                .and_then(serde_json::Value::as_str)
229	            {
230	                let link = ArtifactLink {
231	                    from: artifact.path.clone(),
232	                    field,
233	                    target_contract: *target_contract,
234	                    target_key: target_key.to_owned(),
235	                };
236	                if !graph
237	                    .artifacts
238	                    .iter()
239	                    .any(|target| target.contract == *target_contract && target.key == target_key)
240	                {
241	                    graph.issues.push(GraphIssue {
242	                        path: artifact.path.clone(),
243	                        field,
244	                        message: format!("missing {} target {target_key}", target_contract.id()),
245	                    });
246	                }
247	                graph.links.push(link);
248	            }
249	        }
250	    }
251	    Ok(graph)
252	}
