254	/// Assemble a deterministic one-hop context package without modifying sources.
255	///
256	/// # Errors
257	///
258	/// Returns [`ArtifactError::Absent`] when the requested artifact is not in the
259	/// discovered canonical graph, or filesystem errors from discovery.
260	pub fn assemble_context(
261	    workspace: &Utf8Path,
262	    contract: Contract,
263	    key: &str,
264	) -> Result<ContextPackage, ArtifactError> {
265	    let graph = discover_graph(workspace)?;
266	    let root = graph
267	        .artifacts
268	        .iter()
269	        .find(|artifact| artifact.contract == contract && artifact.key == key)
270	        .cloned()
271	        .ok_or_else(|| ArtifactError::Absent {
272	            path: Utf8PathBuf::from(contract.canonical_directory()).join(format!("{key}.json")),
273	        })?;
274	    let links: Vec<_> = graph
275	        .links
276	        .iter()
277	        .filter(|link| link.from == root.path)
278	        .cloned()
279	        .collect();
280	    let mut artifacts = vec![root.clone()];
281	    for link in &links {
282	        if let Some(target) = graph.artifacts.iter().find(|artifact| {
283	            artifact.contract == link.target_contract && artifact.key == link.target_key
284	        }) {
285	            artifacts.push(target.clone());
286	        }
287	    }
288	    artifacts.sort_by(|left, right| left.path.cmp(&right.path));
289	    let issues = graph
290	        .issues
291	        .into_iter()
292	        .filter(|issue| {
293	            issue.path == root.path || artifacts.iter().any(|artifact| artifact.path == issue.path)
294	        })
295	        .collect();
296	    Ok(ContextPackage {
297	        root,
298	        artifacts,
299	        links,
300	        issues,
301	        git: git_evidence(workspace),
302	    })
303	}
