365	/// Validate a candidate, atomically write its canonical JSON, and report final bytes.
366	///
367	/// # Errors
368	///
369	/// Returns an error without writing a canonical target when validation fails. Write
370	/// failures leave the old canonical target intact because the final rename occurs
371	/// only after a complete same-directory temporary file has been written.
372	pub fn persist_spec(
373	    workspace: &Utf8Path,
374	    candidate: &[u8],
375	) -> Result<PersistenceReceipt, ArtifactError> {
376	    let mut validated =
377	        validate_spec_json(candidate).map_err(|source| ArtifactError::Validation { source })?;
378	    let relative_path = spec_relative_path(&validated.id);
379	    let target = workspace.join(&relative_path);
380	
381	    let object = validated
382	        .value
383	        .as_object_mut()
384	        .ok_or_else(|| ArtifactError::Validation {
385	            source: SpecValidationError::SchemaViolation {
386	                message: "spec@1 accepted a non-object document".to_owned(),
387	            },
388	        })?;
389	    object.insert(
390	        "spec_file_path".to_owned(),
391	        serde_json::Value::String(relative_path.to_string()),
392	    );
393	    validated = validate_spec_value(validated.value)
394	        .map_err(|source| ArtifactError::Validation { source })?;
395	
396	    let parent = target.parent().ok_or_else(|| ArtifactError::Absent {
397	        path: target.clone(),
398	    })?;
399	    fs::create_dir_all(parent).map_err(|source| ArtifactError::Filesystem {
400	        path: parent.to_owned(),
401	        source,
402	    })?;
403	
404	    let mut bytes = serde_json::to_vec_pretty(&validated.value)
405	        .map_err(|source| ArtifactError::Serialization { source })?;
406	    bytes.push(b'\n');
407	    let mut temporary =
408	        NamedTempFile::new_in(parent).map_err(|source| ArtifactError::Filesystem {
409	            path: parent.to_owned(),
410	            source,
411	        })?;
412	    temporary
413	        .write_all(&bytes)
414	        .and_then(|()| temporary.flush())
415	        .and_then(|()| temporary.as_file().sync_all())
416	        .map_err(|source| ArtifactError::Filesystem {
417	            path: target.clone(),
418	            source,
419	        })?;
420	    temporary
421	        .persist(&target)
422	        .map_err(|error| ArtifactError::Filesystem {
423	            path: target.clone(),
424	            source: error.error,
425	        })?;
426	
427	    let final_bytes = fs::read(&target).map_err(|source| ArtifactError::Filesystem {
428	        path: target,
429	        source,
430	    })?;
431	    Ok(PersistenceReceipt {
432	        id: validated.id,
433	        artifact_type: ArtifactType::SpecV1,
434	        path: relative_path.clone(),
435	        content_hash: sha256(&final_bytes),
436	        state: local_state(workspace, &relative_path),
437	    })
438	}
