440	/// Load, revalidate, and describe a canonical `spec@1` artifact.
441	///
442	/// # Errors
443	///
444	/// Returns [`ArtifactError::Absent`] when no canonical file exists, or another
445	/// error when reading or revalidating an existing canonical file fails.
446	pub fn get_spec(workspace: &Utf8Path, id: &ArtifactId) -> Result<ArtifactRecord, ArtifactError> {
447	    let relative_path = spec_relative_path(id);
448	    let target = workspace.join(&relative_path);
449	    let bytes = match fs::read(&target) {
450	        Ok(bytes) => bytes,
451	        Err(source) if source.kind() == std::io::ErrorKind::NotFound => {
452	            return Err(ArtifactError::Absent {
453	                path: relative_path,
454	            });
455	        }
456	        Err(source) => {
457	            return Err(ArtifactError::Filesystem {
458	                path: target,
459	                source,
460	            });
461	        }
462	    };
463	    let validated =
464	        validate_spec_json(&bytes).map_err(|source| ArtifactError::Validation { source })?;
465	    if &validated.id != id {
466	        return Err(ArtifactError::Validation {
467	            source: SpecValidationError::SchemaViolation {
468	                message: "the canonical file ID does not match its requested path".to_owned(),
469	            },
470	        });
471	    }
472	
473	    Ok(ArtifactRecord {
474	        id: validated.id,
475	        artifact_type: ArtifactType::SpecV1,
476	        path: relative_path.clone(),
477	        content_hash: sha256(&bytes),
478	        state: local_state(workspace, &relative_path),
479	        artifact: validated.value,
480	    })
481	}
